open class Animal(val name: String)
class Cat(name: String) : Animal(name)

class Producer<out T>(private val item: T) {
    fun get(): T = item
}

fun nameOf(p: Producer<Animal>) = p.get().name

fun main() {
    val cats: Producer<Cat> = Producer(Cat("Tom"))
    println(nameOf(cats))
}

