fun describe(list: List<*>): String =
    list.joinToString { it?.let { v -> v::class.simpleName } ?: "null" }

fun main() {
    println(describe(listOf(1, "a", null, 2.0)))
}

fun <T> longest(items: List<T>): T?
        where T : CharSequence, T : Comparable<T> =
    items.maxByOrNull { it.length }

fun copy(from: Array<out Any>, to: Array<Any>) {
    for (i in from.indices) to[i] = from[i]
}

fun main() {
    val ints: Array<Int> = arrayOf(1, 2, 3)
    val target = Array<Any>(3) { "-" }
    copy(ints, target)
    println(target.joinToString())
}

interface UiState

abstract class BaseViewModel<S : UiState>(initial: S) : ViewModel() {
    protected val _state = MutableStateFlow(initial)
    val state: StateFlow<S> = _state.asStateFlow()
}

class LoginViewModel : BaseViewModel<LoginState>(LoginState())

sealed class Result<out T> {
    data class Success<out T>(val data: T) : Result<T>()
    data class Error(val e: Throwable) : Result<Nothing>()
    object Loading : Result<Nothing>()
}

fun load(): Result<User> = Result.Loading

class Holder<out T>(private val items: List<T>) {
    fun has(x: @UnsafeVariance T): Boolean = x in items
}

fun main() {
    val h: Holder<Any> = Holder(listOf("a", "b"))
    println(h.has("a"))
    println(h.has(1))
}

open class Shape(val area: Int) : Comparable<Shape> {
    override fun compareTo(other: Shape) = area.compareTo(other.area)
}
class Square(side: Int) : Shape(side * side)

fun <T : Comparable<T>> maxOfAll(items: List<T>): T =
    items.reduce { a, b -> if (a >= b) a else b }

fun main() {
    println(maxOfAll(listOf(Square(2), Square(3))).area)
}
